#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Run from the repo root: ./scripts/setup_accounts.sh
# Keys are read hidden, written only to the gitignored .env, and never printed.
# Requests pass keys as headers through a file descriptor so they don't show in `ps`.

cd "$(dirname "$0")/.."

# http_status URL HEADER [DATA]: prints the HTTP status code only.
http_status() {
  local url="$1" header="$2" data="${3:-}"
  if [[ -n "$data" ]]; then
    curl -s -o /dev/null -w '%{http_code}' -X POST "$url" \
      -H @<(printf '%s\n' "$header") -H 'Content-Type: application/json' \
      -H 'Accept: application/json' -d "$data"
  else
    curl -s -o /dev/null -w '%{http_code}' "$url" \
      -H @<(printf '%s\n' "$header") -H 'Accept: application/json'
  fi
}

# smtp_login USER: true when Gmail accepts USER with the app password in $SMTP_PASSWORD.
# The password reaches Python through the environment, never the command line.
smtp_login() {
  SMTP_USER="$1" SMTP_PASSWORD="$SMTP_PASSWORD" python3 -I -c '
import os, smtplib, sys
try:
    with smtplib.SMTP("smtp.gmail.com", 587, timeout=30) as conn:
        conn.starttls()
        conn.login(os.environ["SMTP_USER"], os.environ["SMTP_PASSWORD"])
except (smtplib.SMTPException, OSError) as e:
    sys.exit(f"  Gmail refused: {type(e).__name__}")
'
}

TOTAL_STAGES=3

banner "Maxfac Papers: Voyage and email setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Voyage AI: API key"
say "Voyage turns abstracts and topics into vectors so we only grade relevant papers."
open_url "https://dash.voyageai.com/"
step "Sign up (or log in)."
step "Open 'API Keys' in the left menu → 'Create new secret key' → copy it (shown once)."
step "Open 'Billing' and add a payment method; without one you're limited to ~3 requests/min."
note "Our volume (~1,000 abstracts a week) stays inside the free allowance."
while true; do
  ask_secret VOYAGE_API_KEY "Paste the Voyage API key:"
  code=$(http_status "https://api.voyageai.com/v1/embeddings" \
    "Authorization: Bearer $VOYAGE_API_KEY" '{"input":["test"],"model":"voyage-4"}')
  if [[ "$code" == "200" ]]; then printf '  %s✓ Voyage key works%s\n' "$GREEN" "$RESET"; break; fi
  warn "Voyage answered HTTP $code (401 = wrong key, 429 = rate limit; add billing)."
  confirm "Try again?" || break
done
write_env VOYAGE_API_KEY "$VOYAGE_API_KEY"
pause


# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Gmail: an account and an app password for sending"
say "For the MVP the app sends its emails through a Gmail account: free, no domain needed."
say "Use a NEW account just for the app: its app password can read and send that mailbox."
open_url "https://accounts.google.com/signup"
step "Create the account (e.g. maxfacpapers@gmail.com). Skip if you already made one."
pause "Press Enter when you're signed in to it."
open_url "https://myaccount.google.com/signinoptions/twosv"
step "Turn on 2-Step Verification (Google requires it for app passwords)."
pause "Press Enter when it's on."
open_url "https://myaccount.google.com/apppasswords"
step "Name it 'Maxfac Papers' → Create → copy the 16-letter password (shown once)."
ask SMTP_USERNAME "The Gmail address:"
SMTP_USERNAME=$(printf %s "$SMTP_USERNAME" | tr -d ' ' | tr '[:upper:]' '[:lower:]')
while true; do
  ask_secret SMTP_PASSWORD "Paste the app password (spaces are fine):"
  SMTP_PASSWORD=$(printf %s "$SMTP_PASSWORD" | tr -d ' ')
  if smtp_login "$SMTP_USERNAME"; then printf '  %s✓ Gmail accepts the app password%s\n' "$GREEN" "$RESET"; break; fi
  warn "Check the address, and that you pasted the app password, not your normal password."
  confirm "Try again?" || break
done
write_env SMTP_HOST "smtp.gmail.com"
write_env SMTP_PORT "587"
write_env SMTP_USERNAME "$SMTP_USERNAME"
write_env SMTP_PASSWORD "$SMTP_PASSWORD"
write_env EMAIL_FROM "$SMTP_USERNAME"   # the app adds the "Tell Me Kort" display name
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Test: send yourself one email through the app"
if [[ -n "$(_existing POSTMARK_SERVER_TOKEN || true)" ]]; then
  warn "POSTMARK_SERVER_TOKEN is set in $ENV_FILE, so the app would use Postmark, not Gmail."
fi
ADMIN_EMAIL=$(_existing ADMIN_EMAIL || true)
if [[ -z "$ADMIN_EMAIL" ]]; then
  warn "ADMIN_EMAIL isn't set in $ENV_FILE; skipping the test send."
  SKIPPED+=("test email (set ADMIN_EMAIL first)")
elif confirm "Send one test email to $ADMIN_EMAIL using the app's own mail code?"; then
  if uv run --quiet python -c '
from app.config import get_settings
from app.email import mailer_for
from app.email.base import EmailMessage
s = get_settings()
mailer_for(s).send(EmailMessage(to=s.admin_email, subject="Maxfac Papers: test email",
    text="If you can read this, the app can send email.",
    html="<p>If you can read this, the app can send email.</p>"))
'; then
    printf '  %s✓ sent; check your inbox (and spam)%s\n' "$GREEN" "$RESET"
  else
    warn "The send failed; the error is above."
    SKIPPED+=("test email (failed; see the error)")
  fi
else
  SKIPPED+=("test email")
fi
pause

SKIPPED+=("On Render: set VOYAGE_API_KEY, SMTP_USERNAME, SMTP_PASSWORD and EMAIL_FROM on the web service and both cron jobs; leave POSTMARK_SERVER_TOKEN empty (LAUNCH.md step 3)")

finish
